package com.siiiweb.article.entity;import javax.persistence.*;import java.time.*;@Entity public class Article{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public String title; public String category; public String tags; @Column(length=500) public String summary; @Lob public String content; public Long views=0L; public String status="PUBLISHED"; public LocalDateTime createdAt=LocalDateTime.now();}
